import java.io.*;import java.sql.*;import java.util.*;import java.math.*;import net.sf.jasperreports.engine.*;import net.sf.jasperreports.engine.data.JRMapCollectionDataSource;
public class VerificaReporteProductos {public static void main(String[] args)throws Exception{try(InputStream in=VerificaReporteProductos.class.getResourceAsStream("/restaurante/reportes/productos.jrxml")){JasperReport r=JasperCompileManager.compileReport(in);Map<String,Object> p=new HashMap<>();p.put("DESDE",java.sql.Date.valueOf("2026-01-01"));p.put("HASTA",java.sql.Date.valueOf("2026-12-31"));Map<String,Object> row=new HashMap<>();row.put("id_producto",1);row.put("nombre","Producto");row.put("unidades",new BigDecimal("2"));row.put("importe",new BigDecimal("25.00"));JasperPrint j=JasperFillManager.fillReport(r,p,new JRMapCollectionDataSource(Collections.singletonList(row)));byte[] pdf=JasperExportManager.exportReportToPdf(j);if(j.getPages().isEmpty()||pdf.length<100||pdf[0]!='%'||pdf[1]!='P')throw new AssertionError("PDF no generado");System.out.println("OK: productos vendidos compila y produce PDF simulado");}}}

